using junit.framework;

public class TRICORE_BE_O3_EmulatorTest : ProcessorEmulatorTestAdapter {

	private static readonly string LANGUAGE_ID = "tricore:LE:32:default";
	private static readonly string COMPILER_SPEC_ID = "default";

	private static readonly string[] REG_DUMP_SET = new string[] {};

	public TRICORE_BE_O3_EmulatorTest(string name)
    : base(name, LANGUAGE_ID, COMPILER_SPEC_ID, REG_DUMP_SET)
    {
	}

	/* @Override */
	protected string getProcessorDesignator() {
		return "tricore_GCC_O3";
	}

	/* @Override */
	protected void initializeState(EmulatorTestRunner testRunner, Program program)
    {
		base.initializeState(testRunner, program);
		testRunner.setRegister("a10", 0x40000000L);  // stack, unused location
		
		testRunner.setRegister("FCX", 0x00020000L);  // free context list start, unused location
		testRunner.setRegister("LCX", 0x00030000L);  // free context list max
		
		testRunner.setRegister("PCXI", 0x0L);        // current thread context list
	}
	
	

	/* @Override */
	protected void setAnalysisOptions(Options analysisOptions) {
		base.setAnalysisOptions(analysisOptions);
		analysisOptions.setBoolean("Reference", false); // too many bad disassemblies
	}

	public static Test suite() {
		return ProcessorEmulatorTestAdapter.buildEmulatorTestSuite(typeof(TRICORE_BE_O3_EmulatorTest));
	}
